.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] {
  --acu-bg-0: #f3f6ff;
  --acu-bg-1: #ffffff;
  --acu-bg-2: #eaf0fc;
  --acu-sidebar-bg: #eef2fe;
  --acu-hover-overlay: #716ec313;
  --acu-border: #cbd4ef;
  --acu-border-2: #dce3f4;
  --acu-text-1: #293554;
  --acu-text-2: #475a79;
  --acu-text-3: #61708c;
  --acu-accent: #6552ad;
  --acu-accent-2: #2b81a1;
  --acu-on-accent: #ffffff;
  --acu-accent-glow: #dddafa;
  --acu-success: #207568;
  --acu-warning: #98600d;
  --acu-danger: #b53f62;
  --acu-radius-lg: 18px;
  --acu-radius-md: 12px;
  --acu-radius-sm: 7px;
  --acu-shadow: 0 12px 38px #4e568a20;
  color-scheme: light;
  accent-color: #6552ad;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .acu-v2-app__shell {
  background: #f3f6ff;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-v2-sidebar, .acu-visualizer-surface__sidebar, .acu-visualizer-surface__mobile-nav) {
  background: linear-gradient(165deg, #e6f5fc 0%, #f2edff 65%, #e7edff 100%);
  border-color: #d2d8ef;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-v2-main, .acu-visualizer-surface__workspace) {
  background-image: radial-gradient(ellipse at 100% 0, #ded8fc55, transparent 65%);
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-masthead {
  position: relative;
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  min-width: 0;
  min-height: 76px;
  gap: 12px;
  padding: 5px 24px 5px 18px;
  border-bottom: 1px solid #cbd8f0;
  background: linear-gradient(100deg, #e3f5ff 0%, #eeedff 55%, #e4ddfb 100%);
  color: #293554;
  overflow: hidden;
  box-sizing: border-box;
  pointer-events: none;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-masthead::after {
  content: "";
  position: absolute;
  inset: 0 0 0 auto;
  width: 38%;
  background: repeating-conic-gradient(#7970bb10 0% 25%, transparent 0% 50%) 0 0 / 36px 36px;
  mask-image: linear-gradient(90deg, transparent, #000);
  pointer-events: none;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-avatar {
  display: block;
  flex: 0 0 auto;
  width: 68px;
  height: 68px;
  object-fit: contain;
  filter: drop-shadow(0 3px 4px #7773aa25);
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-avatar[hidden] { display: none; }
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-copy {
  position: relative;
  z-index: 1;
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-eyebrow {
  color: #655799;
  font: 700 9px/1.3 ui-monospace, monospace;
  letter-spacing: 3px;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-name {
  color: #343b71;
  font-size: 22px;
  font-weight: 750;
  line-height: 1.25;
  letter-spacing: 2px;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-caption {
  color: #58688b;
  font-size: 11px;
  line-height: 1.45;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-pieces {
  position: relative;
  z-index: 1;
  margin-left: auto;
  padding: 0 8px;
  font: 40px/1 Georgia, serif;
  letter-spacing: 8px;
  color: #a49bd4;
  white-space: nowrap;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-pieces::before,
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-pieces::after {
  content: "";
  position: absolute;
  width: 12px;
  height: 17px;
  top: 5px;
  background: #8ba2d5;
  border-radius: 80% 10% 70% 20%;
  transform: rotate(-30deg);
  left: -26px;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-pieces::after {
  left: -14px;
  transform: scaleX(-1) rotate(-30deg);
  background: #ad93d9;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-portrait {
  position: relative;
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 0;
  margin: 0 0 16px;
  padding: 4px 8px 14px;
  border: 1px solid #cdd8f0;
  border-radius: 16px;
  background: radial-gradient(ellipse at 50% 30%, #ffffff, #f2efffd9 75%);
  box-shadow: 0 5px 18px #7b7cb511;
  text-align: center;
  pointer-events: none;
  overflow: hidden;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-portrait::before {
  content: "";
  position: absolute;
  inset: auto 0 0;
  height: 8px;
  background: repeating-conic-gradient(#a39dcc66 0% 25%, #dfeafc 0% 50%) 0 0 / 16px 16px;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-portrait .shiro-db-avatar { width: 112px; height: 112px; }
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-portrait .shiro-db-name { font-size: 18px; }
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-portrait .shiro-db-eyebrow { font-size: 8px; }
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-portrait .shiro-db-pieces {
  position: absolute;
  top: 22px;
  right: 0;
  font-size: 22px;
  letter-spacing: 1px;
  opacity: .65;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-shortcuts {
  display: grid;
  flex: 0 0 auto;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  margin: -8px 0 16px;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-shortcut {
  appearance: none;
  display: block;
  min-width: 0;
  min-height: 44px;
  padding: 8px 4px;
  border: 1px solid #bfc5e4;
  border-radius: 9px;
  color: #4b407a;
  background: linear-gradient(120deg, #f8fcff, #efebfb);
  font: 600 12px/1.4 var(--acu-font-ui, sans-serif);
  text-align: center;
  cursor: pointer;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-shortcut:hover { background: #e3def7; border-color: #9a8dc2; }
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-shortcut:focus-visible { outline: 2px solid #6552ad; outline-offset: 2px; }
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-notices { display: none; }
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-v2-sidebar__brand, .acu-visualizer-nav__brand) {
  border-bottom: 1px solid #ccd7ef;
  padding-bottom: 14px;
  margin-bottom: 12px;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-v2-app__header, .acu-visualizer-surface__topbar) { background: #fcfcff; }
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-v2-sidebar__group-title, .acu-visualizer-nav__head h2) {
  color: #65749a;
  letter-spacing: 1px;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-v2-sidebar__item--active, .acu-visualizer-nav__sheet-row.is-active, .acu-visualizer-nav__global-item.is-active) {
  background: linear-gradient(110deg, #ddecff, #e8ddfb);
  color: #44366f;
  border-color: #bdb4e5;
  box-shadow: inset 3px 0 #8677be;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-panel, .acu-visualizer-surface__data-card) {
  box-shadow: 0 4px 16px #59669a0b;
  border-color: #d2d9ed;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-panel__header, .acu-visualizer-surface__card-header) {
  background: linear-gradient(100deg, #f0f7ff, #f5f1fd);
  border-bottom-color: #d3ddf0;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .acu-visualizer-surface__card-header {
  padding: 9px 10px;
  border-radius: 8px;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-v2-form-fill-page__status-table, .acu-v2-advanced-tools-page__sql-result-table) th {
  color: #443b72;
  background: #e7e8fa;
  border-bottom-color: #babfdf;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-v2-form-fill-page__status-table, .acu-v2-advanced-tools-page__sql-result-table) tbody tr:nth-child(even) { background: #f4f7ff; }
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-v2-form-fill-page__status-table, .acu-v2-advanced-tools-page__sql-result-table) tbody tr:hover { background: #ece7fc; }
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .acu-btn--primary {
  background: linear-gradient(120deg, #6667b8, #7360ae);
  border-color: #6552ad;
  color: #fff;
  box-shadow: 0 2px 7px #6652ad20;
}
.acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-input, .acu-textarea, .acu-select):focus-visible {
  outline: 2px solid #7566ad;
  outline-offset: 2px;
}
/* The upstream shell already owns dvh and safe-area padding. Keep those coordinates
   and native events; only enlarge touch targets and reflow its confirmed v2 DOM. */
@media (min-width: 721px) {
  /* Upstream App.vue switches to its desktop sidebar above 720px. AcuIconButton's
     display:inline-flex !important otherwise leaks this inactive mobile control. */
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .acu-v2-app__header-left > .acu-v2-app__menu { display: none !important; }
}
@media (min-width: 768px) {
  /* The editor uses a separate 767px mobile breakpoint and the same icon component. */
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .acu-visualizer-surface__topbar-context > .acu-visualizer-surface__mobile-menu { display: none !important; }
}
@media (max-width: 767px), (pointer: coarse) and (max-width: 1024px) {
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] {
    --acu-font-size-body: 14px;
    --acu-font-size-body-lg: 15px;
    --acu-font-size-caption: 12px;
    --acu-panel-padding: 12px;
    --acu-page-gap: 12px;
    --acu-button-height-md: 44px;
    --acu-button-height-sm: 44px;
    --acu-control-height-md: 44px;
    --acu-control-height-sm: 44px;
    --acu-icon-button-size-md: 44px;
    --acu-icon-button-size-sm: 44px;
    --acu-segment-height-md: 44px;
    --acu-segment-height-sm: 44px;
  }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-input, .acu-textarea) {
    --acu-font-size-body: 16px;
    --acu-font-size-body-lg: 16px;
    --acu-font-size-caption: 16px;
    min-height: 44px;
    font-size: 16px;
    scroll-margin-block: 16px;
  }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-select__trigger, .acu-select__item, .acu-v2-sidebar__item, .acu-v2-app__theme-option, .acu-visualizer-nav__sheet-row, .acu-visualizer-nav__global-item) {
    min-height: 44px;
  }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-icon-btn, .shiro-db-shortcut, .acu-btn, .acu-select__trigger, .acu-v2-sidebar__item) {
    touch-action: manipulation;
  }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .acu-visualizer-surface__field-locks .acu-icon-btn {
    --acu-icon-btn-size: 44px;
    --acu-icon-btn-font-size: 13px;
  }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .acu-visualizer-surface__field-locks { opacity: 1; }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .acu-visualizer-surface__page-button {
    width: 44px;
    min-width: 44px;
    height: 44px;
    flex-basis: 44px;
  }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .acu-visualizer-surface__field-preview { min-height: 44px; }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-v2-sidebar, .acu-visualizer-surface__mobile-nav, .acu-visualizer-surface__workspace) {
    overscroll-behavior: contain;
    scroll-padding-block: 12px;
  }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-v2-app__shell, .acu-v2-app__mobile-nav-layer, .acu-visualizer-surface__mobile-nav-layer, .acu-v2-drawer-layer),
  #acu-app-v2:has(> .acu-v2-app[data-shiro-database-theme="blank-chess-v1"]) > .acu-dialog-layer {
    inset: var(--shiro-db-viewport-top, 0px) auto auto var(--shiro-db-viewport-left, 0px);
    width: var(--shiro-db-viewport-width, 100dvw);
    height: var(--shiro-db-viewport-height, 100dvh);
    min-height: 0;
    max-height: var(--shiro-db-viewport-height, 100dvh);
  }
  #acu-app-v2:has(> .acu-v2-app[data-shiro-database-theme="blank-chess-v1"]) > .acu-dialog-layer .acu-dialog {
    max-height: 100%;
    min-width: 0;
    overflow-wrap: anywhere;
    overscroll-behavior: contain;
    --acu-control-height-md: 44px;
    --acu-button-height-md: 44px;
  }
  #acu-app-v2:has(> .acu-v2-app[data-shiro-database-theme="blank-chess-v1"]) > .acu-dialog-layer .acu-input { font-size: 16px; }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-notices {
    display: block;
    width: 100%;
    min-height: 44px;
    margin: 0 0 10px;
    border: 1px solid #c6cbee;
    border-radius: 9px;
    background: #fafaff;
    color: #504378;
    font: 600 13px/1.4 var(--acu-font-ui, sans-serif);
    cursor: pointer;
    touch-action: manipulation;
  }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-notices:focus-visible { outline: 2px solid #6552ad; outline-offset: 2px; }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .acu-panel__header { flex-wrap: wrap; gap: 6px; }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] :is(.acu-panel__header-right, .acu-panel__actions) { max-width: 100%; flex-wrap: wrap; }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .acu-panel__title { flex-basis: 90px; overflow-wrap: anywhere; }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .acu-panel__body { min-width: 0; overflow-wrap: anywhere; }
}
@media (max-width: 767px) {
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-masthead { display: var(--shiro-db-masthead-display, flex); min-height: 30px; gap: 7px; padding: 2px 10px; }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-masthead .shiro-db-avatar { width: 26px; height: 26px; }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-masthead .shiro-db-name { font-size: 13px; letter-spacing: .5px; }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-masthead :is(.shiro-db-caption, .shiro-db-eyebrow, .shiro-db-pieces) { display: none; }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .acu-v2-app__header { padding: 4px 8px; }
  .acu-v2-app[data-shiro-database-theme="blank-chess-v1"] .shiro-db-portrait {
    flex-direction: row;
    gap: 8px;
    margin-bottom: 12px;
    padding: 4px 8px 10px;
    text-align: left;
